import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 자료 구분 값과 열 구성은 세무회계사무소 제공 양식을 받기 전의 임시 구성이다.
// 가정: file은 SpreadsheetML(엑셀에서 열리는 XML) 문서를 base64로 인코딩한 문자열이다.
type Col = [string, string];

interface Kind {
  sheet: string;
  columns: Col[];
  sql: string;
}

const KINDS: Record<string, Kind> = {
  VOUCHER: {
    sheet: '전표분개',
    columns: [
      ['voucherNo', '전표번호'],
      ['voucherDate', '전표일자'],
      ['lineNo', '분개순번'],
      ['accountCode', '계정과목 코드'],
      ['accountName', '계정과목 명칭'],
      ['dcType', '차대 구분'],
      ['amount', '금액'],
      ['partnerCode', '거래처 코드'],
      ['partnerName', '거래처 명칭'],
      ['summary', '적요'],
    ],
    sql:
      'SELECT v.voucher_no AS "voucherNo", to_char(v.voucher_date, \'YYYY-MM-DD\') AS "voucherDate", ' +
      'l.line_no AS "lineNo", a.account_code AS "accountCode", a.account_name AS "accountName", ' +
      'l.dc_type AS "dcType", l.amount AS "amount", p.partner_code AS "partnerCode", ' +
      'p.partner_name AS "partnerName", l.summary AS "summary" ' +
      'FROM voucher_line l ' +
      'JOIN journal_voucher v ON v.journal_voucher_id = l.journal_voucher_id ' +
      'JOIN account_item a ON a.account_item_id = l.account_item_id ' +
      'LEFT JOIN partner p ON p.partner_id = l.partner_id ' +
      'WHERE v.voucher_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date) ' +
      'ORDER BY v.voucher_date, v.journal_voucher_id, l.line_no',
  },
  ACCOUNT_ITEM: {
    sheet: '계정과목',
    columns: [
      ['accountCode', '계정과목 코드'],
      ['accountName', '계정과목 명칭'],
      ['accountType', '계정 유형'],
    ],
    sql:
      'SELECT a.account_code AS "accountCode", a.account_name AS "accountName", a.account_type AS "accountType" ' +
      'FROM account_item a ' +
      'WHERE EXISTS (SELECT 1 FROM voucher_line l ' +
      'JOIN journal_voucher v ON v.journal_voucher_id = l.journal_voucher_id ' +
      'WHERE l.account_item_id = a.account_item_id ' +
      'AND v.voucher_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)) ' +
      'ORDER BY a.account_code',
  },
  PARTNER: {
    sheet: '거래처',
    columns: [
      ['partnerCode', '거래처 코드'],
      ['partnerName', '거래처 명칭'],
      ['businessRegNo', '사업자등록번호'],
      ['representativeName', '대표자명'],
      ['taxInvoice', '세금계산서 여부'],
    ],
    sql:
      'SELECT p.partner_code AS "partnerCode", p.partner_name AS "partnerName", ' +
      'p.business_reg_no AS "businessRegNo", p.representative_name AS "representativeName", ' +
      'CASE WHEN p.tax_invoice_yn THEN \'Y\' ELSE \'N\' END AS "taxInvoice" ' +
      'FROM partner p ' +
      'WHERE EXISTS (SELECT 1 FROM voucher_line l ' +
      'JOIN journal_voucher v ON v.journal_voucher_id = l.journal_voucher_id ' +
      'WHERE l.partner_id = p.partner_id ' +
      'AND v.voucher_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)) ' +
      'ORDER BY p.partner_code',
  },
};

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function xmlText(value: unknown): string {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function cell(value: unknown): string {
  if (value === null || value === undefined) {
    return '<Cell><Data ss:Type="String"></Data></Cell>';
  }
  if (typeof value === 'number') {
    return '<Cell><Data ss:Type="Number">' + String(value) + '</Data></Cell>';
  }
  return '<Cell><Data ss:Type="String">' + xmlText(value) + '</Data></Cell>';
}

function toWorkbook(kind: Kind, rows: Record<string, unknown>[]): string {
  const lines: string[] = [];
  lines.push('<?xml version="1.0" encoding="UTF-8"?>');
  lines.push('<Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet">');
  lines.push('<Worksheet ss:Name="' + xmlText(kind.sheet) + '"><Table>');
  lines.push('<Row>' + kind.columns.map((c) => cell(c[1])).join('') + '</Row>');
  for (const row of rows) {
    lines.push('<Row>' + kind.columns.map((c) => cell(row[c[0]])).join('') + '</Row>');
  }
  lines.push('</Table></Worksheet></Workbook>');
  return lines.join('\n');
}

@Controller('api/v1')
export class FnSfr00606Controller {
  @Post('/tax-office-exports')
  @HttpCode(200)
  async exportTaxOfficeExcel(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const startDate = data['startDate'];
    const endDate = data['endDate'];
    const dataType = data['dataType'];
    if (typeof startDate !== 'string' || !DATE_PATTERN.test(startDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변환 대상 기간 시작일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (typeof endDate !== 'string' || !DATE_PATTERN.test(endDate)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변환 대상 기간 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
    }
    if (startDate > endDate) {
      throw new ApiError(400, 'VALIDATION_FAILED', '시작일은 종료일보다 늦을 수 없습니다.');
    }
    if (typeof dataType !== 'string' || !Object.keys(KINDS).includes(dataType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '변환 대상 자료 구분을 선택해 주세요.');
    }
    const kind = KINDS[dataType];
    return transaction(async (db) => {
      const rows = (await db.query(kind.sql, { startDate, endDate })) as Record<string, unknown>[];
      if (rows.length === 0) {
        throw new ApiError(404, 'EXPORT_DATA_NOT_FOUND', '변환 대상 자료가 없습니다.');
      }
      try {
        const xml = toWorkbook(kind, rows);
        const file = Buffer.from(xml, 'utf-8').toString('base64');
        return { file };
      } catch (e) {
        throw new ApiError(422, 'EXPORT_CONVERT_FAILED', '엑셀 변환 중 오류가 발생했습니다. 자료를 확인한 뒤 다시 시도해 주세요.');
      }
    });
  }
}

