import { useState } from 'react';
import {
  call,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  ErrorText,
  Field,
  Form,
  Num,
  Select,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

const DATA_TYPES: [string, string][] = [
  ['VOUCHER', '전표 분개 내역'],
  ['ACCOUNT_ITEM', '계정과목'],
  ['PARTNER', '거래처'],
];

function typeName(value: unknown): string {
  const found = DATA_TYPES.find((t) => t[0] === value);
  return found ? found[1] : String(value);
}

function download(file: string, name: string) {
  const bin = atob(file);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) {
    bytes[i] = bin.charCodeAt(i);
  }
  const blob = new Blob([bytes], { type: 'application/vnd.ms-excel' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = name;
  a.click();
  URL.revokeObjectURL(url);
}

export default function FnSfr00606Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [dataType, setDataType] = useState('');
  const [history, setHistory] = useState<Row[]>([]);
  const [formError, setFormError] = useState('');

  const openDrawer = () => {
    setStartDate('');
    setEndDate('');
    setDataType('');
    setFormError('');
    setOpen(true);
  };

  const submit = async () => {
    setFormError('');
    if (!startDate || !endDate || !dataType) {
      throw new Error('대상 기간과 자료 구분을 모두 입력해 주세요.');
    }
    if (startDate > endDate) {
      throw new Error('시작일은 종료일보다 늦을 수 없습니다.');
    }
    const res = await call<{ file: string }>('POST', '/tax-office-exports', role, {
      startDate,
      endDate,
      dataType,
    });
    download(res.file, 'tax-office-' + dataType.toLowerCase() + '-' + startDate + '_' + endDate + '.xls');
    const entry: Row = {
      id: history.length + 1,
      period: startDate + ' ~ ' + endDate,
      dataType,
      doneAt: new Date().toISOString(),
    };
    setHistory([entry, ...history]);
    setOpen(false);
    notify('엑셀 파일로 변환했습니다.');
  };

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>이번 접속 변환</h2>
        <Tiles items={[['변환 건수', <Num value={history.length} />]]} />
      </section>
      <section className="box span-8">
        <h2>변환 내역</h2>
        <Band total={history.length}>
          <button type="button" onClick={openDrawer}>엑셀 변환</button>
        </Band>
        <DataTable
          columns={[
            { key: 'period', label: '변환 대상 기간' },
            { key: 'dataType', label: '변환 대상 자료 구분', render: (r) => typeName(r.dataType) },
            { key: 'doneAt', label: '변환 일시', render: (r) => <DateText value={r.doneAt} time /> },
          ]}
          rows={history}
          empty="변환한 내역이 없습니다."
        />
      </section>
      {open && (
        <Drawer title="세무회계사무소 연계용 엑셀 변환" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="변환 및 다운로드">
            <Field label="변환 대상 기간 시작일" required>
              <DateInput value={startDate} onChange={setStartDate} />
            </Field>
            <Field label="변환 대상 기간 종료일" required>
              <DateInput value={endDate} onChange={setEndDate} />
            </Field>
            <Field label="변환 대상 자료 구분" required>
              <Select value={dataType} onChange={setDataType} options={DATA_TYPES} />
            </Field>
          </Form>
          {formError && <ErrorText text={formError} />}
        </Drawer>
      )}
    </div>
  );
}
